"""moderngl core implemented on Blender's `gpu` module (Metal, iOS).

The bundled Blender ships a real offscreen **Metal** backend with a runtime
GLSL->MSL cross-compiler (device-verified: gpu.init / GPUShader /
GPUOffScreen).  That is exactly the machinery moderngl needs, so instead of
porting OpenGL to iOS we adapt moderngl's object model onto it:

    moderngl.Context      -> gpu.init() + state tracking
    moderngl.Program      -> gpu.types.GPUShader     (GLSL -> MSL by Blender)
    moderngl.Buffer       -> CPU bytes, uploaded into GPUVertBuf at VAO build
    moderngl.VertexArray  -> gpu.types.GPUBatch
    moderngl.Framebuffer  -> gpu.types.GPUOffScreen  (color+depth)
    moderngl.Texture      -> gpu.types.GPUTexture

Covered: standalone context, buffers, vertex/fragment programs, uniforms
(float/vec/mat/int/sampler), simple + multi-attribute VAOs, index buffers,
point/line/triangle modes, framebuffer clear/render/read, RGBA8/RGBA32F
textures, blend + depth state.

Not covered (raises with a clear message): geometry/tessellation/compute
shaders, transform feedback, queries/scopes, texture arrays/3D/cube,
renderbuffers-as-such, buffer orphaning semantics.  GL row order: reads are
bottom-up like OpenGL.
"""

import re
import struct

# GL-compatible constants (moderngl re-exports these values)
NOTHING = 0
POINTS = 0x0000
LINES = 0x0001
LINE_LOOP = 0x0002
LINE_STRIP = 0x0003
TRIANGLES = 0x0004
TRIANGLE_STRIP = 0x0005
TRIANGLE_FAN = 0x0006
BLEND = 0x0BE2
DEPTH_TEST = 0x0B71
CULL_FACE = 0x0B44

_MODE_TO_BATCH = {
    POINTS: "POINTS",
    LINES: "LINES",
    LINE_LOOP: "LINE_LOOP",
    LINE_STRIP: "LINE_STRIP",
    TRIANGLES: "TRIS",
    TRIANGLE_STRIP: "TRI_STRIP",
    TRIANGLE_FAN: "TRI_FAN",
}

_gpu = None          # blender gpu module, resolved lazily
_IFACE_N = 0         # unique stage-interface names


class Error(Exception):
    pass


def _backend():
    """Import + initialise Blender's gpu module (Metal) once."""
    global _gpu
    if _gpu is not None:
        return _gpu
    try:
        import bpy                      # noqa: F401  (forces blender init)
        import gpu
    except Exception as e:              # host / no bpy
        raise Error(
            "moderngl-on-Metal needs the bundled Blender gpu module "
            f"(import failed: {e}). On desktop use real moderngl.") from e
    try:
        if hasattr(gpu, "init"):
            gpu.init()                  # offscreen Metal context (idempotent)
    except Exception as e:
        raise Error(f"gpu.init() failed: {e}") from e
    _gpu = gpu
    return gpu


def _strip_glsl(src):
    """moderngl-style GLSL 330 -> Blender raw-shader GLSL.

    Blender's raw GPUShader path wants no #version line and no layout
    qualifiers; everything else (in/out/uniform/gl_Position/texture())
    passes through its GLSL->MSL cross-compiler.
    """
    src = re.sub(r"^\s*#\s*version[^\n]*\n", "", src, count=1, flags=re.M)
    src = re.sub(r"layout\s*\([^)]*\)\s*", "", src)
    return src


_FMT_CHAR = {"f": ("FLOAT", 4), "i": ("INT", 4), "u": ("UINT", 4)}


def _parse_fmt(fmt):
    """Parse a moderngl buffer format like '2f 3f' / '2f4' / '3f 1i'.

    Returns list of (components, kind, bytesize) per attribute.
    """
    out = []
    for tok in fmt.split():
        m = re.fullmatch(r"(\d*)([fiu])(\d?)", tok)
        if not m:
            raise Error(f"unsupported buffer format token: {tok!r}")
        comps = int(m.group(1) or 1)
        kind, default_sz = _FMT_CHAR[m.group(2)]
        size = int(m.group(3) or default_sz)
        if size != 4:
            raise Error(f"only 4-byte components supported (got {tok!r})")
        out.append((comps, kind, size))
    return out


class Buffer:
    def __init__(self, ctx, data=None, reserve=0, dynamic=False):
        self.ctx = ctx
        self.dynamic = dynamic
        self._data = bytearray(data if data is not None else bytes(reserve))

    @property
    def size(self):
        return len(self._data)

    def write(self, data, offset=0):
        data = bytes(data)
        self._data[offset:offset + len(data)] = data

    def read(self, size=-1, offset=0):
        end = None if size < 0 else offset + size
        return bytes(self._data[offset:end])

    def clear(self):
        self._data = bytearray(len(self._data))

    def orphan(self, size=-1):
        if size >= 0 and size != len(self._data):
            self._data = bytearray(size)

    def release(self):
        self._data = bytearray()


class _UniformProxy:
    """prog['name'] handle; assignment is deferred to draw time."""

    def __init__(self, program, name):
        self._program = program
        self._name = name

    @property
    def value(self):
        return self._program._uniforms.get(self._name)

    @value.setter
    def value(self, v):
        self._program._uniforms[self._name] = v

    def write(self, data):
        # raw bytes -> floats (moderngl uniform .write is float payload)
        n = len(data) // 4
        self._program._uniforms[self._name] = struct.unpack(f"<{n}f", bytes(data))


_GLSL_TYPE = {
    "float": "FLOAT", "vec2": "VEC2", "vec3": "VEC3", "vec4": "VEC4",
    "int": "INT", "ivec2": "IVEC2", "ivec3": "IVEC3", "ivec4": "IVEC4",
    "uint": "UINT", "uvec2": "UVEC2", "uvec3": "UVEC3", "uvec4": "UVEC4",
    "bool": "BOOL", "mat3": "MAT3", "mat4": "MAT4",
}

_DECL_RE = re.compile(
    r"^\s*(flat\s+|noperspective\s+)?(in|out|uniform)\s+(\w+)\s+(\w+)\s*;\s*$",
    re.M)


def _split_decls(src):
    """Pull global in/out/uniform declarations out of a GLSL source.

    Returns (body_without_decls, ins, outs, uniforms) where each entry is
    (glsl_type, name, interp) with interp in {'smooth','flat'}.
    """
    ins, outs, unis = [], [], []

    def _grab(m):
        interp = "flat" if (m.group(1) or "").strip() == "flat" else "smooth"
        kind, typ, name = m.group(2), m.group(3), m.group(4)
        if kind == "in":
            ins.append((typ, name, interp))
        elif kind == "out":
            outs.append((typ, name, interp))
        else:
            unis.append((typ, name, interp))
        return ""                       # strip the line from the body

    body = _DECL_RE.sub(_grab, src)
    return body, ins, outs, unis


def _create_shader(gpu, vs_raw, fs_raw):
    """Compile GLSL via whichever GPUShader path this Blender build allows.

    Older builds accept gpu.types.GPUShader(vs, fs) directly; the iOS Metal
    build disables direct instantiation ("cannot create 'GPUShader'
    instances"), so declarations are parsed out of the source and fed to
    GPUShaderCreateInfo + gpu.shader.create_from_info(), with only the
    function bodies passed through as GLSL (Blender cross-compiles to MSL).
    """
    vs = _strip_glsl(vs_raw)
    fs = _strip_glsl(fs_raw)
    try:
        return gpu.types.GPUShader(vs, fs)
    except Exception:
        pass                            # fall through to CreateInfo path

    vs_body, vs_in, vs_out, vs_uni = _split_decls(vs)
    fs_body, fs_in, fs_out, fs_uni = _split_decls(fs)

    info = gpu.types.GPUShaderCreateInfo()
    for slot, (typ, name, _i) in enumerate(vs_in):
        t = _GLSL_TYPE.get(typ)
        if t is None:
            raise Error(f"unsupported vertex input type {typ!r}")
        info.vertex_in(slot, t, name)

    # VS outs -> FS ins via a stage interface (unique name per program —
    # Blender registers interface blocks by name)
    if vs_out:
        global _IFACE_N
        _IFACE_N += 1
        iface = gpu.types.GPUStageInterfaceInfo(f"mgl_iface_{_IFACE_N}")
        for typ, name, interp in vs_out:
            t = _GLSL_TYPE.get(typ)
            if t is None:
                raise Error(f"unsupported varying type {typ!r}")
            (iface.flat if interp == "flat" else iface.smooth)(t, name)
        info.vertex_out(iface)

    for slot, (typ, name, _i) in enumerate(fs_out):
        t = _GLSL_TYPE.get(typ)
        if t is None:
            raise Error(f"unsupported fragment output type {typ!r}")
        info.fragment_out(slot, t, name)

    samp_slot = 0
    seen = set()
    for typ, name, _i in vs_uni + fs_uni:
        if name in seen:
            continue
        seen.add(name)
        if typ == "sampler2D":
            info.sampler(samp_slot, "FLOAT_2D", name)
            samp_slot += 1
        else:
            t = _GLSL_TYPE.get(typ)
            if t is None:
                raise Error(f"unsupported uniform type {typ!r}")
            info.push_constant(t, name)

    info.vertex_source(vs_body)
    info.fragment_source(fs_body)
    return gpu.shader.create_from_info(info)


class Program:
    def __init__(self, ctx, vertex_shader, fragment_shader,
                 geometry_shader=None, **kwargs):
        if geometry_shader or kwargs.get("tess_control_shader") \
                or kwargs.get("tess_evaluation_shader"):
            raise Error("geometry/tessellation shaders are not supported on "
                        "the iOS Metal backend")
        gpu = _backend()
        self.ctx = ctx
        try:
            self._shader = _create_shader(gpu, vertex_shader, fragment_shader)
        except Error:
            raise
        except Exception as e:
            raise Error(f"GLSL compile failed (via Blender GLSL->MSL): {e}") from e
        self._uniforms = {}
        # sampler uniform names, in declaration order across both stages
        self._samplers = re.findall(
            r"uniform\s+sampler2D\s+(\w+)", vertex_shader + fragment_shader)
        self._sampler_units = {}   # unit(int) -> Texture

    def __getitem__(self, name):
        return _UniformProxy(self, name)

    def __setitem__(self, name, value):
        self._uniforms[name] = value

    def get(self, name, default=None):
        try:
            return self[name]
        except Exception:
            return default

    def _apply_uniforms(self):
        sh = self._shader
        for name, v in self._uniforms.items():
            if name in self._samplers:
                continue                    # handled via sampler binding
            try:
                if isinstance(v, bool):
                    sh.uniform_bool(name, [v])
                elif isinstance(v, int):
                    sh.uniform_int(name, [v])
                elif isinstance(v, float):
                    sh.uniform_float(name, v)
                else:
                    seq = list(v)
                    if seq and isinstance(seq[0], (tuple, list)):
                        seq = [x for row in seq for x in row]   # mat rows
                    if all(isinstance(x, int) for x in seq):
                        sh.uniform_int(name, seq)
                    else:
                        sh.uniform_float(name, [float(x) for x in seq])
            except Exception:
                pass                        # unused/optimised-out uniform

    def _apply_samplers(self):
        sh = self._shader
        for name in self._samplers:
            unit = self._uniforms.get(name, 0)
            tex = self._sampler_units.get(int(unit))
            if tex is not None:
                try:
                    sh.uniform_sampler(name, tex._tex)
                except Exception:
                    pass

    def release(self):
        self._shader = None


class Texture:
    def __init__(self, ctx, size, components=4, data=None, dtype="f1"):
        gpu = _backend()
        self.ctx = ctx
        self.size = tuple(size)
        self.components = components
        self.dtype = dtype
        w, h = self.size
        if dtype == "f1":
            fmt = "RGBA8"
        elif dtype == "f4":
            fmt = "RGBA32F"
        else:
            raise Error(f"texture dtype {dtype!r} not supported (f1/f4)")
        buf = None
        if data is not None:
            data = bytes(data)
            floats = []
            if dtype == "f1":
                px = struct.unpack(f"<{len(data)}B", data)
                scale = 1.0 / 255.0
                px = [p * scale for p in px]
            else:
                px = list(struct.unpack(f"<{len(data)//4}f", data))
            # expand to RGBA
            if components == 4:
                floats = px
            else:
                for i in range(0, len(px), components):
                    chunk = list(px[i:i + components])
                    chunk += [0.0] * (3 - len(chunk)) + [1.0]
                    floats += chunk
            buf = gpu.types.Buffer("FLOAT", len(floats), floats)
        try:
            if buf is not None:
                self._tex = gpu.types.GPUTexture((w, h), format=fmt, data=buf)
            else:
                self._tex = gpu.types.GPUTexture((w, h), format=fmt)
        except Exception as e:
            raise Error(f"GPUTexture failed: {e}") from e

    def use(self, location=0):
        # bind this texture to a unit; programs resolve units at draw
        self.ctx._bound_textures[int(location)] = self

    def release(self):
        self._tex = None


class VertexArray:
    def __init__(self, ctx, program, content, index_buffer=None, mode=None):
        gpu = _backend()
        self.ctx = ctx
        self.program = program
        self._default_mode = mode if mode is not None else TRIANGLES

        fmt = gpu.types.GPUVertFormat()
        attr_specs = []     # (name, comps, kind, offset, stride, buffer)
        nverts = None
        for buf, fmt_str, *names in content:
            parsed = _parse_fmt(fmt_str)
            if len(parsed) != len(names):
                raise Error(f"format {fmt_str!r} declares {len(parsed)} "
                            f"attributes but {len(names)} names given")
            stride = sum(c * s for c, _, s in parsed)
            off = 0
            n = buf.size // stride if stride else 0
            nverts = n if nverts is None else min(nverts, n)
            for (comps, kind, size), name in zip(parsed, names):
                fmt.attr_add(id=name, comp_type=("F32" if kind == "FLOAT"
                                                 else "I32" if kind == "INT"
                                                 else "U32"),
                             len=comps, fetch_mode=("FLOAT" if kind == "FLOAT"
                                                    else "INT"))
                attr_specs.append((name, comps, kind, off, stride, buf))
                off += comps * size
        self._nverts = nverts or 0

        vbo = gpu.types.GPUVertBuf(len=self._nverts, format=fmt)
        for name, comps, kind, off, stride, buf in attr_specs:
            raw = bytes(buf._data)
            ch = "f" if kind == "FLOAT" else ("i" if kind == "INT" else "I")
            vals = []
            for v in range(self._nverts):
                base = v * stride + off
                vals.append(struct.unpack_from(f"<{comps}{ch}", raw, base))
            vbo.attr_fill(id=name, data=vals)
        self._vbo = vbo

        kwargs = {}
        if index_buffer is not None:
            idx_raw = bytes(index_buffer._data)
            idx = list(struct.unpack(f"<{len(idx_raw)//4}I", idx_raw))
            kwargs["elem"] = gpu.types.GPUIndexBuf(
                type=_MODE_TO_BATCH.get(self._default_mode, "TRIS"), seq=idx)
        self._batches = {}      # mode -> GPUBatch (built lazily per mode)
        self._index_kwargs = kwargs

    def _batch(self, mode):
        gpu = _backend()
        b = self._batches.get(mode)
        if b is None:
            btype = _MODE_TO_BATCH.get(mode)
            if btype is None:
                raise Error(f"render mode {mode} not supported")
            b = gpu.types.GPUBatch(type=btype, buf=self._vbo,
                                   **self._index_kwargs)
            self._batches[mode] = b
        return b

    def render(self, mode=None, vertices=-1, first=0, instances=1):
        gpu = _backend()
        mode = self._default_mode if mode is None else mode
        batch = self._batch(mode)
        fbo = self.ctx._current_fbo
        prog = self.program

        def _draw():
            self.ctx._apply_state()
            prog._sampler_units = dict(self.ctx._bound_textures)
            sh = prog._shader
            sh.bind()
            prog._apply_uniforms()
            prog._apply_samplers()
            batch.draw(sh)

        if fbo is not None:
            with fbo._off.bind():
                _draw()
        else:
            _draw()

    def release(self):
        self._vbo = None
        self._batches = {}


class Framebuffer:
    def __init__(self, ctx, size, components=4, dtype="f1", samples=0):
        gpu = _backend()
        self.ctx = ctx
        self.size = tuple(size)
        self.components = components
        self.dtype = dtype
        fmt = "RGBA8" if dtype == "f1" else "RGBA32F"
        try:
            self._off = gpu.types.GPUOffScreen(self.size[0], self.size[1],
                                               format=fmt)
        except TypeError:
            self._off = gpu.types.GPUOffScreen(self.size[0], self.size[1])
        self.viewport = (0, 0, self.size[0], self.size[1])

    def use(self):
        self.ctx._current_fbo = self

    def clear(self, red=0.0, green=0.0, blue=0.0, alpha=0.0, depth=1.0,
              viewport=None, color=None):
        gpu = _backend()
        if color is not None:
            red, green, blue, alpha = (tuple(color) + (0.0, 0.0, 0.0, 0.0))[:4]
        with self._off.bind():
            fb = gpu.state.active_framebuffer_get()
            fb.clear(color=(red, green, blue, alpha), depth=depth)

    def read(self, viewport=None, components=3, attachment=0, alignment=1,
             dtype="f1"):
        buf = self._off.texture_color.read()
        vals = _buffer_to_list(buf)
        w, h = self.size
        out = bytearray()
        # source is RGBA float rows (bottom-up, GL order)
        if dtype == "f1":
            # values may already be 0..255 ints (RGBA8 read) or 0..1 floats
            as_int = all(isinstance(v, int) for v in vals[:4])
            for i in range(0, w * h * 4, 4):
                px = vals[i:i + 4]
                for c in range(components):
                    v = px[c]
                    out.append(int(v) & 0xFF if as_int
                               else max(0, min(255, int(round(v * 255)))))
            return bytes(out)
        elif dtype == "f4":
            flat = []
            for i in range(0, w * h * 4, 4):
                flat.extend(float(x) for x in vals[i:i + 4][:components])
            return struct.pack(f"<{len(flat)}f", *flat)
        raise Error(f"read dtype {dtype!r} not supported")

    def release(self):
        try:
            self._off.free()
        except Exception:
            pass


def _buffer_to_list(buf):
    """gpu.types.Buffer -> flat python list (handles nested dims)."""
    try:
        lst = buf.to_list()
    except Exception:
        lst = list(buf)
    while lst and isinstance(lst[0], (list, tuple)):
        lst = [x for row in lst for x in row]
    return lst


class Context:
    def __init__(self):
        _backend()
        self._current_fbo = None
        self._bound_textures = {}
        self._enabled = set()
        self.screen = None
        gpu = _gpu
        try:
            self.info = {"GL_RENDERER":
                         "Blender Metal offscreen (" +
                         gpu.platform.backend_type_get() + ")"}
        except Exception:
            self.info = {"GL_RENDERER": "Blender Metal offscreen"}

    # --- object factories -------------------------------------------------
    def buffer(self, data=None, reserve=0, dynamic=False):
        return Buffer(self, data=data, reserve=reserve, dynamic=dynamic)

    def program(self, vertex_shader=None, fragment_shader=None, **kw):
        if not vertex_shader or not fragment_shader:
            raise Error("both vertex_shader and fragment_shader are required")
        return Program(self, vertex_shader, fragment_shader, **kw)

    def vertex_array(self, program, content, index_buffer=None,
                     index_element_size=4, mode=None):
        if isinstance(content, Buffer):
            raise Error("use simple_vertex_array or pass a content list")
        if index_element_size != 4:
            raise Error("only 4-byte indices supported")
        return VertexArray(self, program, content, index_buffer, mode)

    def simple_vertex_array(self, program, buffer, *attributes,
                            index_buffer=None, mode=None):
        # Infer per-attribute component counts from the shader itself, like
        # real moderngl does — Blender exposes attrs_info_get() on GPUShader.
        n = len(attributes)
        if n == 0:
            raise Error("no attributes given")
        comps_by_name = {}
        try:
            for name, typ in program._shader.attrs_info_get():
                t = (typ or "").upper()
                comps_by_name[name] = (int(t[-1]) if t.startswith("VEC")
                                       else 1 if t in ("FLOAT", "INT", "UINT")
                                       else 4 if "MAT4" in t
                                       else 3 if "MAT3" in t else None)
        except Exception:
            pass
        fmt_parts = []
        for a in attributes:
            c = comps_by_name.get(a)
            if c is None:
                # heuristic fallback: single attribute -> derive from an even
                # split; otherwise require an explicit format
                if n == 1:
                    floats = buffer.size // 4
                    for cand in (4, 3, 2, 1):
                        if floats % cand == 0:
                            c = cand
                            break
                if c is None:
                    raise Error(
                        f"could not infer components for attribute {a!r} — "
                        "use ctx.vertex_array with an explicit format")
            fmt_parts.append(f"{c}f")
        return VertexArray(self, program,
                           [(buffer, " ".join(fmt_parts), *attributes)],
                           index_buffer, mode)

    def texture(self, size, components=4, data=None, samples=0,
                alignment=1, dtype="f1"):
        return Texture(self, size, components=components, data=data,
                       dtype=dtype)

    def simple_framebuffer(self, size, components=4, samples=0, dtype="f1"):
        return Framebuffer(self, size, components=components, dtype=dtype)

    def framebuffer(self, color_attachments=None, depth_attachment=None):
        # moderngl attaches textures; GPUOffScreen owns its own — accept a
        # single Texture attachment and mirror its size/dtype.
        if isinstance(color_attachments, (list, tuple)):
            if len(color_attachments) != 1:
                raise Error("only one color attachment supported")
            att = color_attachments[0]
        else:
            att = color_attachments
        if isinstance(att, Texture):
            return Framebuffer(self, att.size, components=att.components,
                               dtype=att.dtype)
        raise Error("framebuffer() needs a Texture color attachment "
                    "(renderbuffers are not supported)")

    def renderbuffer(self, size, components=4, samples=0, dtype="f1"):
        # moderngl code commonly does ctx.framebuffer([ctx.renderbuffer(s)]);
        # a Texture works identically for that flow here.
        return Texture(self, size, components=components, dtype=dtype)

    # --- state -------------------------------------------------------------
    def enable(self, flags):
        self._enabled.add(flags)

    def disable(self, flags):
        self._enabled.discard(flags)

    def enable_only(self, flags):
        self._enabled = {flags} if flags else set()

    def _apply_state(self):
        gpu = _gpu
        try:
            gpu.state.blend_set("ALPHA" if BLEND in self._enabled else "NONE")
            gpu.state.depth_test_set(
                "LESS_EQUAL" if DEPTH_TEST in self._enabled else "NONE")
        except Exception:
            pass

    def clear(self, red=0.0, green=0.0, blue=0.0, alpha=0.0, depth=1.0,
              viewport=None, color=None):
        if self._current_fbo is not None:
            self._current_fbo.clear(red, green, blue, alpha, depth,
                                    viewport, color)

    def finish(self):
        pass

    def release(self):
        pass

    # moderngl exposes constants on the context too
    NOTHING, POINTS, LINES = NOTHING, POINTS, LINES
    LINE_LOOP, LINE_STRIP, TRIANGLES = LINE_LOOP, LINE_STRIP, TRIANGLES
    TRIANGLE_STRIP, TRIANGLE_FAN = TRIANGLE_STRIP, TRIANGLE_FAN
    BLEND, DEPTH_TEST, CULL_FACE = BLEND, DEPTH_TEST, CULL_FACE


def create_standalone_context(require=None, **kwargs):
    return Context()


def create_context(standalone=False, require=None, **kwargs):
    return Context()
